package power

import (
	_ "embed"
	"encoding/json"
	"runtime"
	"slices"
	"strings"
)

// The action manifest is the app's action registry (actions.ts) as data,
// generated by scripts/action-manifest.ts. The Runner checks keys.yaml, `do:`
// steps and layout files against it; `lazybox do --list` prints it; a hook may
// run only the actions it marks safe.

//go:embed actions.manifest.json
var manifestJSON []byte

// RegistryAction is one action of the app's registry.
type RegistryAction struct {
	ID       string  `json:"id"`
	Title    string  `json:"title"`
	Group    string  `json:"group"`
	Scope    string  `json:"scope"`
	Keys     string  `json:"keys"`
	Other    *string `json:"otherKeys,omitempty"`
	Required bool    `json:"required,omitempty"`
	Fixed    bool    `json:"fixed,omitempty"`
	Hold     bool    `json:"hold,omitempty"`
	// Safe: a hook may run it (it only shows, focuses or arranges).
	Safe        bool   `json:"safe,omitempty"`
	Destructive bool   `json:"destructive,omitempty"`
	Argument    string `json:"argument,omitempty"`
}

// Manifest is the registry with its keymap presets and the layout panel kinds.
type Manifest struct {
	Version int              `json:"version"`
	Actions []RegistryAction `json:"actions"`
	Presets []string         `json:"presets"`
	// Keymaps: platform ("mac", "other") → preset → action → keys, resolved.
	Keymaps        map[string]map[string]map[string]string `json:"keymaps"`
	LayoutPanels   []string                                `json:"layoutPanels"`
	BuiltinLayouts []struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	} `json:"builtinLayouts"`
	byID map[string]*RegistryAction
}

var registry = func() *Manifest {
	m := &Manifest{}
	if err := json.Unmarshal(manifestJSON, m); err != nil {
		panic("power: actions.manifest.json: " + err.Error())
	}
	m.byID = map[string]*RegistryAction{}
	for i := range m.Actions {
		m.byID[m.Actions[i].ID] = &m.Actions[i]
	}
	return m
}()

// Registry is the app's action registry.
func Registry() *Manifest { return registry }

// Action returns the registry action with this id.
func (m *Manifest) Action(id string) (RegistryAction, bool) {
	a, ok := m.byID[id]
	if !ok {
		return RegistryAction{}, false
	}
	return *a, true
}

// Keymap is a preset's keymap on this machine's platform ("" is vim), Mod+ resolved.
func (m *Manifest) Keymap(preset string) map[string]string {
	if preset == "" {
		preset = "vim"
	}
	out := map[string]string{}
	for k, v := range m.Keymaps[platform()][preset] {
		out[k] = v
	}
	return out
}

func platform() string {
	if runtime.GOOS == "darwin" {
		return "mac"
	}
	return "other"
}

// ActionIDs are every registry action's id.
func (m *Manifest) ActionIDs() []string {
	ids := make([]string, 0, len(m.Actions))
	for _, a := range m.Actions {
		ids = append(ids, a.ID)
	}
	return ids
}

// ValidPanel reports whether a layout may place this panel kind.
func (m *Manifest) ValidPanel(kind string) bool { return slices.Contains(m.LayoutPanels, kind) }

// Suggest names the closest of candidates to a mistyped value, or "".
func Suggest(value string, candidates []string) string {
	best, bestDistance := "", 1<<30
	for _, c := range candidates {
		if d := distance(strings.ToLower(value), strings.ToLower(c)); d < bestDistance {
			best, bestDistance = c, d
		}
	}
	if bestDistance > max(2, len([]rune(value))/3) {
		return ""
	}
	return best
}

// didYouMean is ` (did you mean "x"?)` or "".
func didYouMean(value string, candidates []string) string {
	if s := Suggest(value, candidates); s != "" && s != value {
		return ` (did you mean "` + s + `"?)`
	}
	return ""
}

// distance is the Levenshtein distance between two strings.
func distance(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur := make([]int, len(rb)+1)
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev = cur
	}
	return prev[len(rb)]
}
